#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int minDeletionSize(char** strs, int strsSize) {
    int m = (int)strlen(strs[0]);
    int* dp = (int*)malloc((size_t)m * sizeof(int));
    for (int j = 0; j < m; ++j) dp[j] = 1;

    for (int j = 1; j < m; ++j) {
        for (int i = 0; i < j; ++i) {
            int ok = 1;
            for (int r = 0; r < strsSize; ++r) {
                if (strs[r][i] > strs[r][j]) {
                    ok = 0;
                    break;
                }
            }
            if (ok && dp[i] + 1 > dp[j]) dp[j] = dp[i] + 1;
        }
    }

    int best = dp[0];
    for (int j = 1; j < m; ++j)
        if (dp[j] > best) best = dp[j];

    free(dp);
    return m - best;
}

int main(void) {
    char line[20000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    int capacity = 128, count = 0;
    char** strs = (char**)malloc((size_t)capacity * sizeof(char*));

    for (char* p = line; *p; ) {
        if (*p != '"') {
            ++p;
            continue;
        }

        ++p;
        char* start = p;
        while (*p && *p != '"') ++p;
        if (!*p) break;

        size_t len = (size_t)(p - start);
        char* s = (char*)malloc(len + 1);
        memcpy(s, start, len);
        s[len] = '\0';

        if (count == capacity) {
            capacity *= 2;
            strs = (char**)realloc(strs, (size_t)capacity * sizeof(char*));
        }
        strs[count++] = s;

        ++p;
    }

    if (count > 0) {
        printf("%d\n", minDeletionSize(strs, count));
    }

    for (int i = 0; i < count; ++i) free(strs[i]);
    free(strs);
    return 0;
}

