class Solution {
public:
    int minDeletionSize(vector<string>& strs) {
        int m = (int)strs[0].size();
        vector<int> dp(m, 1);
        for (int j = 1; j < m; ++j) {
            for (int i = 0; i < j; ++i) {
                bool ok = true;
                for (const string& row : strs) {
                    if (row[i] > row[j]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) dp[j] = max(dp[j], dp[i] + 1);
            }
        }
        return m - *max_element(dp.begin(), dp.end());
    }
};

