import java.io.*;
import java.util.*;
import java.util.regex.*;

class Solution {
    public int minDeletionSize(String[] strs) {
        int m = strs[0].length();
        int[] dp = new int[m];
        Arrays.fill(dp, 1);
        for (int j = 1; j < m; j++) {
            for (int i = 0; i < j; i++) {
                boolean ok = true;
                for (String row : strs) {
                    if (row.charAt(i) > row.charAt(j)) {
                        ok = false;
                        break;
                    }
                }
                if (ok) dp[j] = Math.max(dp[j], dp[i] + 1);
            }
        }
        int best = 0;
        for (int x : dp) best = Math.max(best, x);
        return m - best;
    }
}

public class Main {
    static String[] parseStrings(String line) {
        Matcher m = Pattern.compile("\"([a-z]+)\"").matcher(line);
        List<String> list = new ArrayList<>();
        while (m.find()) list.add(m.group(1));
        return list.toArray(new String[0]);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] strs = parseStrings(line);
        System.out.println(new Solution().minDeletionSize(strs));
    }
}

